SELECT DATE_FORMAT(paid_at, 'yyyy-MM') AS paid_month, method, CASE WHEN YEAR(paid_at) < 2024 THEN 'before_2024' WHEN YEAR(paid_at) = 2024 THEN '2024' ELSE 'after_2024' END AS paid_cohort, ROUND(STDDEV(amount), 2) AS stddev_amount FROM payments GROUP BY DATE_FORMAT(paid_at, 'yyyy-MM'), method, CASE WHEN YEAR(paid_at) < 2024 THEN 'before_2024' WHEN YEAR(paid_at) = 2024 THEN '2024' ELSE 'after_2024' END HAVING ROUND(STDDEV(amount), 2) >= 76
